"use client";

import Image from "next/image";
import Link from "next/link";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

type Banner = { id: string; title: string; subtitle: string | null; image: string; ctaLabel: string | null; ctaHref: string | null };
const INTERVAL = 6000;

export function HeroCarousel({ banners }: { banners: Banner[] }) {
  const [i, setI] = useState(0);
  const [paused, setPaused] = useState(false);
  const touchX = useRef<number | null>(null);
  const n = banners.length;

  useEffect(() => {
    if (n < 2 || paused) return;
    const t = setTimeout(() => setI((x) => (x + 1) % n), INTERVAL);
    return () => clearTimeout(t);
  }, [n, paused, i]);
  if (!n) return null;
  const go = (d: number) => setI((x) => (x + d + n) % n);

  return (
    <section
      className="relative overflow-hidden bg-ink"
      aria-roledescription="carousel"
      aria-label="Featured offers"
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      onTouchStart={(e) => (touchX.current = e.touches[0].clientX)}
      onTouchEnd={(e) => {
        if (touchX.current === null) return;
        const dx = e.changedTouches[0].clientX - touchX.current;
        if (Math.abs(dx) > 40) go(dx < 0 ? 1 : -1);
        touchX.current = null;
      }}
    >
      {banners.map((b, idx) => {
        const active = idx === i;
        return (
          <div
            key={b.id}
            className={cn("transition-opacity duration-1000 ease-out", active ? "relative z-10 opacity-100" : "absolute inset-0 opacity-0")}
            aria-hidden={!active}
            aria-roledescription="slide"
            aria-label={`${idx + 1} of ${n}`}
          >
            <div className="relative h-[320px] sm:h-[400px] lg:h-[440px]">
              {/* The image stays mounted; the zoom animation restarts whenever this slide becomes active. */}
              <div className={cn("absolute inset-0", active && "animate-ken-burns")}>
                <Image src={b.image} alt="" fill priority={idx === 0} sizes="100vw" className="object-cover" />
              </div>
              <div className="absolute inset-0 bg-gradient-to-r from-black/65 via-black/30 to-transparent" />
              {active && (
                <div key={`txt-${i}`} className="container-x relative flex h-full flex-col justify-center text-white">
                  <h2 className="animate-fade-up max-w-xl font-display text-3xl font-bold leading-tight sm:text-5xl">{b.title}</h2>
                  {b.subtitle && <p className="animate-fade-up mt-3 max-w-lg text-sm text-white/90 [animation-delay:120ms] sm:text-lg">{b.subtitle}</p>}
                  {b.ctaHref && (
                    <Link href={b.ctaHref} className="btn-brass press animate-fade-up group mt-6 w-fit px-6 py-3 text-base shadow-lg [animation-delay:240ms]">
                      {b.ctaLabel ?? "Shop now"} <ChevronRight className="h-4 w-4 transition-transform group-hover:translate-x-1" aria-hidden />
                    </Link>
                  )}
                </div>
              )}
            </div>
          </div>
        );
      })}
      {n > 1 && (
        <>
          <button onClick={() => go(-1)} className="press absolute left-3 top-1/2 z-20 hidden -translate-y-1/2 rounded-full bg-white/80 p-2 text-ink shadow transition hover:scale-110 hover:bg-white sm:block" aria-label="Previous slide"><ChevronLeft className="h-5 w-5" /></button>
          <button onClick={() => go(1)} className="press absolute right-3 top-1/2 z-20 hidden -translate-y-1/2 rounded-full bg-white/80 p-2 text-ink shadow transition hover:scale-110 hover:bg-white sm:block" aria-label="Next slide"><ChevronRight className="h-5 w-5" /></button>
          <div className="absolute bottom-4 left-1/2 z-20 flex -translate-x-1/2 gap-2">
            {banners.map((b, idx) => (
              <button key={b.id} onClick={() => setI(idx)} className="relative h-1.5 w-8 overflow-hidden rounded-full bg-white/35" aria-label={`Go to slide ${idx + 1}`} aria-current={idx === i}>
                {/* Progress fill doubles as the auto-advance timer. */}
                <span
                  key={idx === i ? `p-${i}-${paused}` : "idle"}
                  className="absolute inset-y-0 left-0 rounded-full bg-white"
                  style={idx === i ? { width: paused ? "100%" : undefined, animation: paused ? "none" : `grow-w ${INTERVAL}ms linear forwards` } : { width: idx < i ? "100%" : "0%" }}
                />
              </button>
            ))}
          </div>
        </>
      )}
    </section>
  );
}
